<body>
    <div id="desktop">
        <div class="desktop-content">
            <!-- Files Window -->
            <div id="files-window" class="window">
                <div class="window-titlebar">
                    <div class="window-title">File Manager</div>
                    <button class="win-close">&times;</button>
                </div>
                <div class="window-content">
                    <div id="files-path">/</div>
                    <button id="files-up">← Up</button>
                    <div class="files-list" id="files-list"></div>
                </div>
            </div>

            <!-- Notepad Window -->
            <div id="notepad-window" class="window">
                <div class="window-titlebar">
                    <div class="window-title">Notepad</div>
                    <button class="win-close">&times;</button>
                </div>
                <div class="window-content">
                    <div style="display: flex; gap: 4px; margin-bottom: 12px; align-items: center;">
                        <div id="tabs"></div>
                        <button id="new-tab">+</button>
                    </div>
                    <textarea id="editor" placeholder="Type here..."></textarea>
                </div>
            </div>
        </div>

        <!-- Taskbar -->
        <div id="taskbar">
            <button id="open-files" class="launcher-button">📁 Files</button>
            <button id="open-notepad" class="launcher-button">📝 Notepad</button>
        </div>
    </div>

    <script>
        // ===== File System Structure =====
        const filesystem = {
            '/': {
                type: 'folder',
                children: {
                    'bin': { type: 'folder', children: {} },
                    'etc': { type: 'folder', children: {} },
                    'home': { type: 'folder', children: {
                        'user': { type: 'folder', children: {
                            'Documents': { type: 'folder', children: {
                                'resume.txt': { type: 'file' },
                                'notes.txt': { type: 'file' }
                            }},
                            'Downloads': { type: 'folder', children: {
                                'image.png': { type: 'file' },
                                'archive.zip': { type: 'file' }
                            }},
                            'Pictures': { type: 'folder', children: {
                                'photo1.jpg': { type: 'file' },
                                'photo2.jpg': { type: 'file' }
                            }}
                        }}
                    }},
                    'usr': { type: 'folder', children: {} },
                    'var': { type: 'folder', children: {} }
                }
            }
        };

        // ===== Window Management =====
        const windows = {
            files: document.getElementById('files-window'),
            notepad: document.getElementById('notepad-window')
        };

        function openWindow(windowName) {
            windows[windowName].classList.add('open');
        }

        function closeWindow(windowName) {
            windows[windowName].classList.remove('open');
        }

        document.getElementById('open-files').addEventListener('click', () => openWindow('files'));
        document.getElementById('open-notepad').addEventListener('click', () => openWindow('notepad'));

        document.querySelectorAll('.win-close').forEach(btn => {
            btn.addEventListener('click', (e) => {
                const window = e.target.closest('.window');
                if (window.id === 'files-window') closeWindow('files');
                else if (window.id === 'notepad-window') closeWindow('notepad');
            });
        });

        // ===== Window Dragging =====
        let draggedWindow = null;
        let dragOffsetX = 0;
        let dragOffsetY = 0;

        document.querySelectorAll('.window-titlebar').forEach(titlebar => {
            titlebar.addEventListener('mousedown', (e) => {
                draggedWindow = titlebar.closest('.window');
                const rect = draggedWindow.getBoundingClientRect();
                dragOffsetX = e.clientX - rect.left;
                dragOffsetY = e.clientY - rect.top;
            });
        });

        document.addEventListener('mousemove', (e) => {
            if (draggedWindow) {
                draggedWindow.style.left = (e.clientX - dragOffsetX) + 'px';
                draggedWindow.style.top = (e.clientY - dragOffsetY) + 'px';
            }
        });

        document.addEventListener('mouseup', () => {
            draggedWindow = null;
        });

        // ===== File Manager =====
        let currentPath = ['/'];

        function getPathString() {
            if (currentPath.length === 1) return '/';
            return '/' + currentPath.slice(1).join('/');
        }

        function getCurrentFolder() {
            let node = filesystem['/'];
            for (let i = 1; i < currentPath.length; i++) {
                node = node.children[currentPath[i]];
            }
            return node;
        }

        function refreshFilesList() {
            const pathStr = getPathString();
            document.getElementById('files-path').textContent = pathStr;

            const folder = getCurrentFolder();
            const filesList = document.getElementById('files-list');
            filesList.innerHTML = '';

            const entries = Object.entries(folder.children).sort((a, b) => {
                if (a[1].type !== b[1].type) return a[1].type === 'folder' ? -1 : 1;
                return a[0].localeCompare(b[0]);
            });

            entries.forEach(([name, item]) => {
                const div = document.createElement('div');
                div.className = `fs-item ${item.type}`;
                div.textContent = name;

                if (item.type === 'folder') {
                    div.addEventListener('dblclick', () => {
                        currentPath.push(name);
                        refreshFilesList();
                        updateUpButton();
                    });
                }

                filesList.appendChild(div);
            });

            updateUpButton();
        }

        function updateUpButton() {
            const upBtn = document.getElementById('files-up');
            upBtn.disabled = currentPath.length === 1;
        }

        document.getElementById('files-up').addEventListener('click', () => {
            if (currentPath.length > 1) {
                currentPath.pop();
                refreshFilesList();
            }
        });

        refreshFilesList();

        // ===== Notepad with Tabs & Persistent Storage =====
        class Notepad {
            constructor() {
                this.tabs = {};
                this.activeTab = null;
                this.nextId = 0;
                this.load();
                this.setupListeners();
                if (Object.keys(this.tabs).length === 0) {
                    this.createTab();
                }
            }

            createTab(content = '') {
                const id = 'tab-' + (this.nextId++);
                this.tabs[id] = {
                    title: 'Untitled ' + Object.keys(this.tabs).length,
                    content: content
                };
                this.setActive(id);
                this.render();
                this.save();
            }

            setActive(tabId) {
                if (this.activeTab) {
                    const activeTab = this.tabs[this.activeTab];
                    const textarea = document.getElementById('editor');
                    activeTab.content = textarea.value;
                }
                this.activeTab = tabId;
                const textarea = document.getElementById('editor');
                textarea.value = this.tabs[tabId].content;
                this.render();
            }

            closeTab(tabId) {
                delete this.tabs[tabId];
                if (this.activeTab === tabId) {
                    const remaining = Object.keys(this.tabs);
                    this.activeTab = remaining.length > 0 ? remaining[0] : null;
                    if (this.activeTab === null) {
                        this.createTab();
                    } else {
                        this.setActive(this.activeTab);
                    }
                }
                this.render();
                this.save();
            }

            render() {
                const tabsContainer = document.getElementById('tabs');
                tabsContainer.innerHTML = '';

                Object.entries(this.tabs).forEach(([id, tab]) => {
                    const tabEl = document.createElement('div');
                    tabEl.className = 'tab' + (id === this.activeTab ? ' active' : '');

                    const titleSpan = document.createElement('span');
                    titleSpan.textContent = tab.title;

                    const closeBtn = document.createElement('span');
                    closeBtn.className = 'tab-close';
                    closeBtn.textContent = '✕';
                    closeBtn.addEventListener('click', (e) => {
                        e.stopPropagation();
                        this.closeTab(id);
                    });

                    tabEl.appendChild(titleSpan);
                    tabEl.appendChild(closeBtn);
                    tabEl.addEventListener('click', () => this.setActive(id));

                    tabsContainer.appendChild(tabEl);
                });
            }

            setupListeners() {
                document.getElementById('new-tab').addEventListener('click', () => this.createTab());
                document.getElementById('editor').addEventListener('input', () => {
                    this.tabs[this.activeTab].content = document.getElementById('editor').value;
                    this.save();
                });
            }

            save() {
                localStorage.setItem('notepad-state', JSON.stringify({
                    tabs: this.tabs,
                    activeTab: this.activeTab,
                    nextId: this.nextId
                }));
            }

            load() {
                const saved = localStorage.getItem('notepad-state');
                if (saved) {
                    const state = JSON.parse(saved);
                    this.tabs = state.tabs;
                    this.activeTab = state.activeTab;
                    this.nextId = state.nextId;
                    this.render();
                    const textarea = document.getElementById('editor');
                    textarea.value = this.tabs[this.activeTab].content;
                }
            }
        }

        const notepad = new Notepad();
    </script>
</body>
</html>
